export type Item = { id: string; number: number; title: string; body: string; pinned: boolean; createdAt: string; archived: boolean; sharedWith: string[] }

// The most recent delete per user, kept until it is undone, the user's notes change again or the user signs out.
export type UndoStore = Map<string, { item: Item; at: number }>

export const createUndoStore = (): UndoStore => new Map()

export const undoKeyOf = (session: { user: string }) => session.user.toLowerCase()
import type { Implement } from '@hozu/data'
import { adminUsers, addNote, myAccess, setAccess, exportNotes, getNote, archiveNote, archiveNotes, removeNotes, lastDeleted, listArchived, listNotes, removeNote, renameNote, updateNote, restoreNote, shareNote, sharedNotes, togglePin, undoDelete, unshareNote } from './model.ts'
import { type Item, type UndoStore, undoKeyOf } from './undo.ts'
import { type UserDirectory, ADMIN, isAdmin } from '../account/users.ts'
import type { NoteStore } from './store.ts'

const view = ({ archived: _, body: __, ...item }: Item) => ({ ...item, sharedWith: [...item.sharedWith] })

export function notesResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  const { notes: store, owners, added, readOnly } = notes
  const keyOf = (session: { user: string }) => session.user.toLowerCase()
  const listOf = (session: { user: string } | null): Item[] => (session ? (store.get(keyOf(session)) ?? []) : [])
  const ownListOf = (session: { user: string } | null) => {
    if (!session) return []
    const list = store.get(keyOf(session)) ?? []
    store.set(keyOf(session), list)
    return list
  }
  // Times of the adds that went through, per user: at most ADD_LIMIT within ADD_WINDOW_MS.
  const ADD_LIMIT = 10
  const ADD_WINDOW_MS = 60_000
  const recentAdds = (session: { user: string }, now: number) => {
    const times = (added.get(keyOf(session)) ?? []).filter((at) => now - at < ADD_WINDOW_MS)
    added.set(keyOf(session), times)
    return times
  }
  // A read-only account may read its notes but not change them.
  const isReadOnly = (session: { user: string } | null) => (session ? readOnly.has(keyOf(session)) : false)
  const forget = (session: { user: string } | null) => {
    if (session) undo.delete(undoKeyOf(session))
  }
  return [
    implement(adminUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (!isAdmin(session)) return fail('NotAdmin', {})
      const keys = new Set([...users.keys(), ...[...store].filter(([, items]) => items.length > 0).map(([key]) => key)])
      return [...keys]
        .map((key) => ({ name: users.get(key) ?? owners.get(key) ?? key, notes: store.get(key)?.length ?? 0, admin: key === ADMIN, readOnly: readOnly.has(key) }))
        .sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()))
    }),
    implement(myAccess, (_, { session, fail }) => (session ? { readOnly: isReadOnly(session) } : fail('Unauthorized', {}))),
    implement(setAccess, ({ name, access }, { session, fail }) => {
      if (!session || !isAdmin(session)) return fail('NotAdmin', {})
      const key = name.trim().toLowerCase()
      const known = users.has(key) || (store.get(key)?.length ?? 0) > 0
      if (!known || key === ADMIN) return fail('NotFound', {})
      if (access === 'read-only') readOnly.add(key)
      else if (access === 'writable') readOnly.delete(key)
      else return fail('Invalid', { message: 'Choose read-only or writable', fields: {} })
      return { name: users.get(key) ?? owners.get(key) ?? key, readOnly: readOnly.has(key) }
    }),
    implement(listNotes, (_, { session, fail }) =>
      session
        ? [...listOf(session).filter((item) => !item.archived && item.pinned), ...listOf(session).filter((item) => !item.archived && !item.pinned)].map(view)
        : fail('Unauthorized', {}),
    ),
    implement(getNote, ({ number }, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const item = /^[1-9][0-9]*$/.test(number) ? listOf(session).find((entry) => entry.number === Number(number)) : undefined
      return item ? { ...item, sharedWith: [...item.sharedWith] } : fail('NotFound', {})
    }),
    implement(exportNotes, ({ format = 'json' }, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const own = listOf(session)
      const notes = [...own.filter((item) => item.pinned), ...own.filter((item) => !item.pinned)].map((item) => ({
        number: item.number,
        title: item.title,
        body: (item.body ?? '').replace(/\r\n?/g, '\n'),
        pinned: item.pinned,
        archived: item.archived,
        createdAt: new Date(item.createdAt).toISOString(),
      }))
      const headers = (type: string) => ({ 'Content-Type': type, 'Content-Disposition': `attachment; filename="notes-${session.user}.${format}"` })
      if (format === 'json') return new Response(JSON.stringify({ user: session.user, notes }), { headers: headers('application/json; charset=utf-8') })
      const cell = (value: string | number | boolean) => {
        const raw = String(value)
        return /[",\r\n]/.test(raw) ? `"${raw.replace(/"/g, '""')}"` : raw
      }
      const columns = ['number', 'title', 'body', 'pinned', 'archived', 'createdAt'] as const
      const lines = [columns.join(','), ...notes.map((note) => columns.map((column) => cell(note[column])).join(','))]
      return new Response(lines.map((line) => `${line}\r\n`).join(''), { headers: headers('text/csv; charset=utf-8') })
    }),
    implement(listArchived, (_, { session, fail }) =>
      session
        ? listOf(session).filter((item) => item.archived).sort((a, b) => b.createdAt.localeCompare(a.createdAt)).map(view)
        : fail('Unauthorized', {}),
    ),
    implement(sharedNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const me = keyOf(session)
      return [...store].flatMap(([owner, items]) =>
        owner === me
          ? []
          : items
              .filter((item) => !item.archived && item.sharedWith.some((name) => name.toLowerCase() === me))
              .map((item) => ({ id: item.id, title: item.title, owner: owners.get(owner) ?? owner })),
      )
    }),
    implement(shareNote, ({ id, name }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id)
      if (!session || !item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = name.trim()
      if (clean.toLowerCase() === keyOf(session)) return fail('Self', {})
      owners.set(keyOf(session), session.user.trim())
      if (!item.sharedWith.some((entry) => entry.toLowerCase() === clean.toLowerCase())) item.sharedWith.push(clean)
      return view(item)
    }),
    implement(unshareNote, ({ id, name }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      item.sharedWith = item.sharedWith.filter((entry) => entry.toLowerCase() !== name.trim().toLowerCase())
      return view(item)
    }),
    implement(archiveNote, ({ id }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.archived = true
      forget(session)
      return view(item)
    }),
    implement(restoreNote, ({ id }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id && entry.archived)
      if (!item) return fail('NotFound', { id })
      item.archived = false
      forget(session)
      return view(item)
    }),
    implement(addNote, ({ title }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      if (!session) return fail('Invalid', { message: 'Signed out', fields: { title: 'Sign in first' } })
      const clean = title.trim()
      if (items.some((item) => item.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      const now = Date.now()
      const times = recentAdds(session, now)
      if (times.length >= ADD_LIMIT) return fail('TooMany', {})
      times.push(now)
      const item = { id: notes.nextId(), number: notes.nextNumber(keyOf(session)), title: clean, body: '', pinned: false, createdAt: new Date().toISOString(), archived: false, sharedWith: [] }
      items.unshift(item)
      forget(session)
      return view(item)
    }),
    implement(removeNote, ({ id }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const at = items.findIndex((item) => item.id === id)
      if (at < 0) return fail('NotFound', { id })
      if (items[at]?.archived) return fail('Archived', { id })
      const [item] = items.splice(at, 1)
      if (session && item) undo.set(undoKeyOf(session), { item, at })
      return { id }
    }),
    implement(removeNotes, ({ ids }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const removed = items.filter((item) => ids.includes(item.id) && !item.archived).map((item) => item.id)
      for (const id of removed) items.splice(items.findIndex((item) => item.id === id), 1)
      forget(session)
      return { ids: removed }
    }),
    implement(archiveNotes, ({ ids }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const archived = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of archived) item.archived = true
      forget(session)
      return { ids: archived.map((item) => item.id) }
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const entry = undo.get(undoKeyOf(session))
      return entry ? { title: entry.item.title } : null
    }),
    implement(undoDelete, (_, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const entry = session ? undo.get(undoKeyOf(session)) : undefined
      if (!session || !entry) return fail('NothingToUndo', {})
      const items = ownListOf(session)
      items.splice(Math.min(entry.at, items.length), 0, entry.item)
      forget(session)
      return view(entry.item)
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      forget(session)
      return view(item)
    }),
    implement(updateNote, ({ id, title, body }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      // A form post sends line breaks as CRLF; count and keep them as one character, like the browser's maxlength.
      const cleanBody = body.replace(/\r\n?/g, '\n').trim()
      const titleError =
        cleanTitle.length === 0 ? 'Write a title first'
          : cleanTitle.length > 60 ? 'Use at most 60 characters'
          : items.some((entry) => entry.id !== id && entry.title.toLowerCase() === cleanTitle.toLowerCase()) ? 'You already have a note with this title'
          : null
      const bodyError = cleanBody.length > 1000 ? 'Use at most 1000 characters in the body' : null
      if (titleError !== null || bodyError !== null)
        return fail('Invalid', { message: 'Check the note', fields: { title: titleError, body: bodyError } })
      item.title = cleanTitle
      item.body = cleanBody
      forget(session)
      return { ...item, sharedWith: [...item.sharedWith] }
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      if (isReadOnly(session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      forget(session)
      return view(item)
    }),
  ]
}
