// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // The highest note number each user has ever had; numbers are never reused.
  numbers: Map<string, number>
  // Store keys of the accounts the admin made read-only.
  readOnly: Set<string>
  nextId: () => string
  nextNumber: (key: string) => number
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  const numbers = new Map<string, number>()
  const nextNumber = (key: string) => {
    const number = (numbers.get(key) ?? 0) + 1
    numbers.set(key, number)
    return number
  }
  // Existing notes are numbered in the order they were added, oldest first.
  const seed = (key: string, notes: [string, string][]) => {
    const items = notes.map(([title, createdAt]) => ({ id: nextId(), number: 0, title, body: '', pinned: false, createdAt, archived: false, sharedWith: [] as string[] }))
    for (const item of [...items].sort((a, b) => a.createdAt.localeCompare(b.createdAt))) item.number = nextNumber(key)
    return items
  }
  return {
    notes: new Map<string, Item[]>([
      ['ada', seed('ada', [['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])],
      ['bob', seed('bob', [["Bob's secret", '2026-01-10T09:00:00.000Z']])],
    ]),
    owners: new Map(),
    added: new Map(),
    numbers,
    readOnly: new Set(),
    nextId,
    nextNumber,
  }
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing, add history, note numbers and read-only setting.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
  store.readOnly.delete(key)
